import{_ as i,o as a,c as t,a0 as s}from"./chunks/framework.D4fUSYzX.js";const k=JSON.parse('{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source and repository mapping, and where the workflow machine lives.","frontmatter":{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source and repository mapping, and where the workflow machine lives."},"headers":[],"relativePath":"getting-started/minimal-config.md","filePath":"getting-started/minimal-config.md"}'),n={name:"getting-started/minimal-config.md"};function o(r,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="minimal-config" tabindex="-1">Minimal Config <a class="header-anchor" href="#minimal-config" aria-label="Permalink to &quot;Minimal Config&quot;">​</a></h1><h2 id="the-config-file" tabindex="-1">The Config file <a class="header-anchor" href="#the-config-file" aria-label="Permalink to &quot;The Config file&quot;">​</a></h2><p>The config lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/my-little-software-factory/config.toml</span></span></code></pre></div><p>or at the path the <code>--config</code> flag names:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.toml</span></span></code></pre></div><p>A config file from an older install migrates once at load, and the start line says so when it runs.</p><p>The shipped Default configuration is a working control plane with the parts it cannot know about your machine left out - no ticket sources and no repository mappings. Everything else is on:</p><ul><li>the three agent types <code>pi</code>, <code>codex</code>, and <code>claude</code></li><li>the four workflow task types: <code>implement</code>, <code>review</code>, <code>rework</code>, and <code>merge</code></li><li>the three security task types, one per security feed source kind</li><li>the workflow&#39;s states and the transitions that move a ticket between them</li><li>the <code>consult</code> and <code>pair</code> Consultation types: <code>consult</code> passes your input straight through, and <code>pair</code> runs a pair programming session with the agent as the driver</li></ul><p><a href="./../configuration/#key-reference">The key reference</a> names every key, its default, and what it does.</p><h2 id="add-a-ticket-source-and-a-repository-mapping" tabindex="-1">Add a ticket source and a repository mapping <a class="header-anchor" href="#add-a-ticket-source-and-a-repository-mapping" aria-label="Permalink to &quot;Add a ticket source and a repository mapping&quot;">​</a></h2><p>Unmark the commented source block in your config file and edit the <code>repositories</code> list to your <code>owner/name</code> values:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refresh-interval-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repositories = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Map where the repository&#39;s checkout lives, one key per <code>owner/name</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;owner/name&quot; = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/src/name&quot;</span></span></code></pre></div><p>Once a repository is mapped, the <a href="./../development/labels.html#making-a-repository-factory-ready">Repository init</a> (<code>i</code> on the repository&#39;s Group header, grouped by repository) makes it factory-ready: it creates the labels your machine writes, writes the convention files, and registers the repository&#39;s sources. A repository the factory has not seen yet stands in no Group: press <code>o</code> in the main view, type to find the repository, and press Enter. The repository needs a local clone on the path the plane names; the plane never clones.</p><h2 id="extend-the-workflow-machine" tabindex="-1">Extend the workflow machine <a class="header-anchor" href="#extend-the-workflow-machine" aria-label="Permalink to &quot;Extend the workflow machine&quot;">​</a></h2><p>The <code>[[states]]</code> tables and each task type&#39;s <code>transition</code> table are where the machine&#39;s states and transitions live in your config, and the file marks them as meant to be extended. The plane owns the workflow labels: it reads a ticket&#39;s position from the labels the ticket carries, and it writes those labels when a task completes, so the agents write no workflow labels. <a href="./../configuration/">The Configuration page</a> carries the complete example and the key reference for every state, transition, and task type key.</p>`,18)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
